// pgvector takes its input as a text literal, '[0.1,0.2,…]', not as a
// Postgres array.  Building it here rather than in the SQL keeps the query
// parameterised: the vector travels as a bound $1, so nothing about the
// embedding can change the shape of the statement.
const row = $json.data && $json.data[0];
if (!row || !Array.isArray(row.embedding)) {
  throw new Error('no embedding in the LiteLLM response: ' + JSON.stringify($json).slice(0, 200));
}
if (row.embedding.length !== 768) {
  throw new Error('expected 768 dimensions from local-embed, got ' + row.embedding.length);
}
return [{
  json: {
    question: $('Synthetic question').first().json.question,
    vec: '[' + row.embedding.join(',') + ']',
  },
}];

// WHAT THE DEMO ACTUALLY CLAIMED, assembled where it can be checked.
//
// The answer is prose and no assertion over prose is worth writing; the
// RETRIEVAL is a fact.  So this node carries both out: the ordered sources
// and their distances, which `aistack samples run W1` asserts against
// w1_expected, and the answer, which it only checks is non-empty.
const answer = (($json.choices || [])[0] || {}).message || {};
const text = (answer.content || '').trim();
if (!text) {
  // FOUND BY QA (NOM-302): a template that records an empty answer and
  // reports success is the defect this whole ticket is about.
  throw new Error('the model returned no content: ' + JSON.stringify($json).slice(0, 300));
}
const hits = $('Nearest chunks (pgvector)').all().map(i => i.json);
if (hits.length === 0) {
  throw new Error('pgvector returned no rows — is the corpus loaded?');
}
return [{
  json: {
    question: $('Synthetic question').first().json.question,
    top_source: hits[0].source,
    sources: hits.map(h => h.source),
    distances: hits.map(h => Number(h.distance)),
    answer: text,
  },
}];
